<script setup lang="ts">
definePageMeta({middleware:'admin'})
const db=useSupabaseClient(),schools=ref<any[]>([]),rows=ref<any[]>([]),schoolId=ref(''),studentNumber=ref(''),given=ref(''),family=ref(''),dob=ref(''),search=ref(''),error=ref(''),success=ref('')
const filtered=computed(()=>rows.value.filter(x=>[x.student_number,x.given_name,x.family_name].join(' ').toLowerCase().includes(search.value.toLowerCase())))
async function load(){const s=await db.from('schools').select('id,name').order('name');schools.value=s.data||[];if(!schoolId.value&&schools.value.length)schoolId.value=schools.value[0].id;await loadStudents()}
async function loadStudents(){if(!schoolId.value){rows.value=[];return}const r=await db.from('students').select('id,student_number,given_name,family_name,date_of_birth').eq('school_id',schoolId.value).order('family_name').limit(500);rows.value=r.data||[];error.value=r.error?.message||''}
onMounted(load)
async function add(){error.value='';success.value='';const r=await db.from('students').insert({school_id:schoolId.value,student_number:studentNumber.value.trim(),given_name:given.value.trim(),family_name:family.value.trim(),date_of_birth:dob.value||null});if(r.error){error.value=r.error.message;return}studentNumber.value='';given.value='';family.value='';dob.value='';success.value='Student added';await loadStudents()}
</script>
<template><div class="page"><div class="shell admin-section"><NuxtLink to="/dashboard">← Dashboard</NuxtLink><h1>Students</h1><p class="notice">Student records are private. Use test data until access controls are verified.</p><label>School<select v-model="schoolId" @change="loadStudents"><option v-for="s in schools" :key="s.id" :value="s.id">{{s.name}}</option></select></label><form class="card editor" @submit.prevent="add"><label>Student number<input v-model="studentNumber" required></label><label>First name<input v-model="given" required></label><label>Last name<input v-model="family" required></label><label>Date of birth (optional)<input v-model="dob" type="date"></label><button class="btn">Add Student</button></form><p v-if="error" class="error">{{error}}</p><p v-if="success" class="success">{{success}}</p><div class="card"><h2>Students</h2><input v-model="search" placeholder="Search student records"><div v-for="s in filtered" :key="s.id" class="data-row"><span>{{s.family_name}}, {{s.given_name}}</span><small>{{s.student_number}}</small></div><p v-if="!filtered.length">No matching students.</p></div></div></div></template>
